package org.brightstats.report;
import java.util.*;import java.util.zip.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import com.google.gson.*;
public final class ReproducibilityChecks {
 static int checks;static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{Path out=Path.of(args[0]);Files.createDirectories(out);JsonObject project=JsonParser.parseString("{\"columnNames\":[\"Private participant score\"],\"observations\":[[1],[2]],\"blocks\":[],\"options\":{\"seed\":44},\"dataPreparation\":{\"sourcePath\":\"C:\\\\private\\\\study.csv\",\"originalCells\":[[\"sensitive-cell\"]]},\"derivation\":{\"private\":true}}").getAsJsonObject();JsonObject original=project.deepCopy();JsonObject report=new JsonObject();report.addProperty("format","bright-stats-report");report.add("project",project.deepCopy());report.add("results",new JsonObject());var settings=ReproducibilityBundle.preview(project,report,new ReproducibilityBundle.Options(false,false));require(settings.entries().stream().noneMatch(e->e.name().equals("project.json")||e.name().equals("analysis.bsreport.json")),"Default excludes source project and report");var text=settings.entries().stream().filter(e->e.name().equals("analysis-settings.json")).findFirst().orElseThrow();JsonObject json=JsonParser.parseString(new String(text.bytes(),StandardCharsets.UTF_8)).getAsJsonObject();require(!json.has("observations")&&!json.has("dataPreparation")&&!json.has("derivation")&&json.getAsJsonObject("options").get("seed").getAsInt()==44,"Settings keep seeds but omit raw history/data");byte[] mutated=text.bytes();mutated[0]=0;require(text.bytes()[0]!='\0',"Reviewed entry bytes cannot mutate through accessors");require(project.equals(original),"Preview never modifies project");try{ReproducibilityBundle.preview(project,report,new ReproducibilityBundle.Options(false,true));throw new AssertionError("Report data exposed without data permission");}catch(IllegalArgumentException expected){checks++;}var full=ReproducibilityBundle.preview(project,report,new ReproducibilityBundle.Options(true,true));require(full.cautions().stream().anyMatch(s->s.contains("filesystem path")),"Encoded Windows source paths produce privacy caution");require(full.entries().stream().filter(e->e.name().equals("analysis.bsreport.json")).count()==1,"Full report included only explicitly");Path target=out.resolve("bundle.zip");Files.deleteIfExists(target);ReproducibilityBundle.write(target,full);try(var zip=new ZipFile(target.toFile())){var manifest=JsonParser.parseString(new String(zip.getInputStream(zip.getEntry("manifest.json")).readAllBytes(),StandardCharsets.UTF_8)).getAsJsonObject();require(zip.size()==full.entries().size()+1,"Bundle has only reviewed entries and manifest");for(var value:manifest.getAsJsonArray("entries")){var entry=value.getAsJsonObject();byte[] bytes=zip.getInputStream(zip.getEntry(entry.get("name").getAsString())).readAllBytes();require(bytes.length==entry.get("bytes").getAsLong()&&ReproducibilityBundle.sha256(bytes).equals(entry.get("sha256").getAsString()),"Independent unzipped bytes match manifest size/hash");}}
 byte[] before=Files.readAllBytes(target);try{ReproducibilityBundle.write(target,full);throw new AssertionError("Overwrote archive");}catch(FileAlreadyExistsException expected){checks++;}require(Arrays.equals(before,Files.readAllBytes(target)),"Existing archive preserved");JsonObject suspect=project.deepCopy();suspect.addProperty("token","example-placeholder");require(ReproducibilityBundle.preview(suspect,null,new ReproducibilityBundle.Options(false,false)).cautions().stream().anyMatch(s->s.contains("credential-like")),"Heuristic credentials caution is explicit");try{new ReproducibilityBundle.Entry("../escape",new byte[0]);throw new AssertionError("Unsafe path allowed");}catch(IllegalArgumentException expected){checks++;}JsonObject receipt=new JsonObject();receipt.addProperty("state","passed");receipt.addProperty("checks",checks);Files.writeString(out.resolve("receipt.json"),receipt.toString());System.out.println(receipt);}
}
